<?php require_once dirname(__DIR__,2).'/bootstrap.php';$me=current_user();$uid=(int)($me['id']??0);$mine=!empty($_GET['mine']);if($mine)$me=require_auth();$owner=$mine?(int)$me['id']:(int)($_GET['user_id']??0);$sid=(int)($_GET['stream_id']??0);$before=(int)($_GET['before_id']??PHP_INT_MAX);$limit=max(1,min(50,(int)($_GET['limit']??30)));$where="r.status='ready' AND r.id<$before AND ".v17_profile_sql('r.user_id',$uid);if($owner)$where.=' AND r.user_id='.$owner;if($sid)$where.=' AND r.stream_id='.$sid;if(!$mine)$where.=" AND (r.visibility IN ('public','vip') OR r.user_id=$uid)";$rows=v17_query('SELECT r.*,u.username,u.display_name,u.avatar_url FROM recordings r JOIN users u ON u.id=r.user_id WHERE '.$where.' ORDER BY r.id DESC LIMIT '.($limit+1))->fetchAll();$more=count($rows)>$limit;$rows=array_slice($rows,0,$limit);$items=array_map('v17_recording',$rows);json_response(['recordings'=>$items,'replays'=>$items,'nextBeforeId'=>$more?(int)end($rows)['id']:null]);